def _validate_braces(self, format):
    """Validate that braces in the format string are properly matched."""
    depth = 0
    i = 0
    while i < len(format):
        if format[i:i+2] == '{{':
            i += 2
            continue
        elif format[i:i+2] == '}}':
            i += 2
            continue
        elif format[i] == '{':
            depth += 1
            # Check for unmatched closing brace within this field
            j = i + 1
            while j < len(format) and format[j] != '}':
                if format[j] == '{':
                    raise ValueError("partial format: nested opening brace without matching closing brace")
                j += 1
            if j >= len(format):
                raise ValueError("partial format: unclosed opening brace")
            # Found closing brace
            i = j + 1
        elif format[i] == '}':
            raise ValueError("partial format: unmatched closing brace")
        else:
            i += 1
    if depth != 0:
        raise ValueError("partial format: unclosed opening brace")

